const Utils={PERSIAN_DIGITS:["۰","۱","۲","۳","۴","۵","۶","۷","۸","۹"],toPersianNum(t){return t==null?"":String(t).replace(/\d/g,e=>this.PERSIAN_DIGITS[+e])},formatPrice(t){if(t==null)return"";const e=Number(t).toLocaleString("en-US");return this.toPersianNum(e)+" تومان"},debounce(t,e=300){let r;return(...o)=>{clearTimeout(r),r=setTimeout(()=>t.apply(this,o),e)}},generateId(){return"id-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2,8)},getStorage(t,e=null){try{const r=localStorage.getItem(t);return r?JSON.parse(r):e}catch{return e}},setStorage(t,e){try{localStorage.setItem(t,JSON.stringify(e))}catch(r){console.warn("localStorage write failed:",r)}},removeStorage(t){localStorage.removeItem(t)},clamp(t,e,r){return Math.max(e,Math.min(r,t))},toPersianDate(t){try{return new Intl.DateTimeFormat("fa-IR",{year:"numeric",month:"long",day:"numeric"}).format(t||new Date)}catch{return""}},timeAgo(t){const e=Math.floor((new Date-t)/1e3);return e<60?"لحظاتی پیش":e<3600?this.toPersianNum(Math.floor(e/60))+" دقیقه پیش":e<86400?this.toPersianNum(Math.floor(e/3600))+" ساعت پیش":this.toPersianNum(Math.floor(e/86400))+" روز پیش"}};
